; MoO1 {0,1,2}
;
; executes a VGA page flip using a special effect for
; screen transition set	through	VGA_PageFlipEffect,
; which	is zeroed out afterward:
;   0 -	simple flip, no	extra effect
;   1 -	left to	right cut (not used in the game)
;   2 -	black cut with the new image fading in
;   3 -	mosaic effect
;   4 -	grow out from a	tile (not used in the game)
;   5 -	writes out the DAC, but	DOES NOT do a page flip
; Attributes: bp-based frame
; int __far PageFlip_FX(void)
proc PageFlip_FX far
push	bp
mov	bp, sp


mov	bx, [_page_flip_effect]
dec	bx
cmp	bx, 4				; switch 5 cases
ja	short @@Sw_PageFlipEffect_Default ; default
shl	bx, 1
jmp	[cs:jt_pageflip_effect+bx]	; switch jump

PageFlipEffect == 1
Dasm shows never assigned

pageflip_effect_00:			; case 0x0
call	RP_VGA_CutRight
jmp	short @@SetDefault_Done
; ---------------------------------------------------------------------------

PageFlipEffect == 2
Dasm shows assigned four times

pageflip_effect_01:			; case 0x1
call	Toggle_Pages
nop
push	cs
call	near ptr Fade_In		; performs a 4-stage image fade-in by manipulating the
					; video	DAC register colors
jmp	short @@SetDefault_Done
; ---------------------------------------------------------------------------

PageFlipEffect == 3
used a bunch

pageflip_effect_02:			; case 0x2
call	Apply_Palette
call	PageFlip_Dissolve
jmp	short @@SetDefault_Done
; ---------------------------------------------------------------------------

PageFlipEffect == 5
Dasm shows never assigned

pageflip_effect_04:			; case 0x4
call	Apply_Palette
jmp	short @@SetDefault_Done
; ---------------------------------------------------------------------------

PageFlipEffect == 4
Dasm shows assigned two	times, only in Main_Screen()

pageflip_effect_03:			; case 0x3
mov	ax, [_screen_seg]
add	ax, 400
push	ax				; picture
push	[GrowOutFrames]			; counter
push	[GrowOutTop]			; y_start
push	[GrowOutLeft]			; x_start
call	Draw_Expanding_Bitmap
add	sp, 8
jmp	short @@SetDefault_Done
; ---------------------------------------------------------------------------

MoO1  PageFlipEffect: 0


if( (PageFlipEffect - 1) > 4 )
? ~ if(	PageFlipEffect > 5 ) ?

@@Sw_PageFlipEffect_Default:		; default
call	Apply_Palette
call	Toggle_Pages


jmp	short $+2
@@SetDefault_Done:			; pfe_None
mov	[_page_flip_effect], 0


pop	bp
retf
endp PageFlip_FX
