; exchanges the	current	draw and display frames	by
; resetting the	VGA read start address,	and swaps
; cursors between the two images
; requires a prior call	to GUI_PageFlipPrep
; int __far Toggle_Pages_No_Draw_Fields(void)
proc Toggle_Pages_No_Draw_Fields far
push	ds


mov	ax, seg	dseg
mov	ds, ax
mov	ax, [GUI_DS_Save]
mov	ds, ax


call	Pointer_Y
push	ax				; l_my
call	Pointer_X
push	ax				; l_mx
call	Check_Mouse_Shape


call	Save_Mouse_Off_Page


call	Draw_Mouse_Off_Page
add	sp, 4


call	Page_Flip


call	Restore_Mouse_Off_Page


call	Copy_Mouse_Off_To_Mouse_Back


call	Restore_Mouse_State


pop	ds
retf
endp Toggle_Pages_No_Draw_Fields
