jmp	short @@ReturnZero
; ---------------------------------------------------------------------------
loc_2D263:
cmp	[mouse_installed], e_ST_FALSE
jz	short loc_2D270
push	cs
call	near ptr Interpret_Mouse_Input	; processes player input on GUI	controls, starting with
					; the keyboard,	followed by an active and passive mouse
					; handler
					; returns with the index of the	last activated control,
					; if any, but can also return zero to indicate no valid
					; input, -1 for	an escape sequence if allowed, or the
					; negative control index in very special cases
					;
					; WARNING: edit	boxes do not return control until they
					; lose focus once they have it
jmp	short loc_2D274
; ---------------------------------------------------------------------------
loc_2D270:
push	cs
call	near ptr RP_GUI_KeyInputOnly	; processes GUI	input using only an emulated mouse
					; pointer and no actual	mouse -	most functionality can
					; still	be accessed this way, with one notable
					; exception being the grid controls
					; returns the index of the control that	received input,
					; 0 if none or already processed, and -1 on escape
					;
					; can be safely	repurposed if it's branch and call are
					; removed
loc_2D274:
mov	si, ax


call	Set_Page_Off


mov	ax, si
