; _AIL_unhook_timer_proc wrapper for DIGPAK drivers
; source: miles214\disk3\ail.asm
; Attributes: library function
; int __far AIL_unhook(void)
proc _AIL_unhook far
push	ds
push	si
push	di
test	[cs:DP_attribs], USES_TICK
jz	short __exit
cmp	[cs:_active_timers], 0		; # of timers currently	registered
jz	short __exit
cmp	[cs:AIL_hooked], 0
jz	short __exit
push	cs
call	near ptr _unhook_timer_proc	; restore default BIOS INT 8 handler
					; source: miles214\disk3\ail.asm
mov	[cs:AIL_hooked], 0
jmp	short __exit
; ---------------------------------------------------------------------------
mov	ax, 693h			; function #12:	ShareTimer
mov	dx, [cs:_PIT_divisor]
int	66h				; reserved for user interrupt
__exit:
pop	di
pop	si
pop	ds
retf
endp _AIL_unhook
; _AIL_hook_timer_process wrapper for DIGPAK drivers
; source: miles214\disk3\ail.asm
; Attributes: library function
; int __far AIL_hook(void)
proc _AIL_hook far
push	ds
push	si
push	di
test	[cs:DP_attribs], USES_TICK
jz	short __exit
cmp	[cs:_active_timers], 0		; # of timers currently	registered
jz	short __exit
cmp	[cs:AIL_hooked], 0
jnz	short __exit
push	cs
call	near ptr _AIL_int_divisor	; returns the current value used internally by the
					; AIL's Process Services to program the IBM PC's 8253
					; PITimer chip for periodic INT	8 (IRQ 0) service
					; source: miles214\disk3\ail.asm
push	ax				; Divisor
push	cs
call	near ptr _set_PIT_divisor	; set 8253 Programmable	Interval Timer to desired
					; IRQ 0	(INT 8)	interval
					; source: miles214\disk3\ail.asm
add	sp, 2
push	cs
call	near ptr _hook_timer_process	; take over the	default	BIOS INT 8 handler
					; source: miles214\disk3\ail.asm
mov	[cs:AIL_hooked], 1
__exit:
pop	di
pop	si
pop	ds
retf
endp _AIL_hook
