; preformats a VOC file	for compatibility
; source: miles214\disk3\ail.asm
; Attributes: library function bp-based	frame
; int __cdecl __far DP_preformat(int SampRate, __int32 BufPtr, __int32 Len)
proc _DP_preformat far
SampRate= word ptr  6
BufPtr=	dword ptr  8
Len= dword ptr	0Ch
push	bp
mov	bp, sp
push	ds
push	si
push	di
test	[cs:DP_attribs], MODIFIES_DATA
jnz	short __continue
jmp	__exit
; ---------------------------------------------------------------------------
__continue:
mov	[word ptr cs:DPT.sndstat], offset playing_flag
mov	[word ptr cs:DPT.sndstat+2], cs
mov	ax, [bp+SampRate]
mov	[cs:DPT.sndfreq], ax
lds	si, [bp+BufPtr]
__while_gt_BLK:
mov	[word ptr cs:DPT.sndptr], si
mov	[word ptr cs:DPT.sndptr+2], ds
cmp	[word ptr bp+Len+2], 0
ja	short __gt_BLK
cmp	[word ptr bp+Len], 8000h
jbe	short __remainder
__gt_BLK:
mov	[cs:DPT.sndlen], 8000h
push	ds
push	si
push	cs
pop	ds
assume ds:_AIL_
mov	si, offset DPT
mov	ax, 68Ah			; function #3: MassageAudio
int	66h				; reserved for user interrupt
pop	si
pop	ds
assume ds:dseg
push	bx
push	cx
mov	bx, ds
xor	cx, cx
shl	bx, 1
rcl	cx, 1
shl	bx, 1
rcl	cx, 1
shl	bx, 1
rcl	cx, 1
shl	bx, 1
rcl	cx, 1
add	bx, si
adc	cx, 0
add	bx, 8000h
adc	cx, 0
mov	si, bx
and	si, 0Fh
shr	cx, 1
rcr	bx, 1
shr	cx, 1
rcr	bx, 1
shr	cx, 1
rcr	bx, 1
shr	cx, 1
rcr	bx, 1
mov	ds, bx
pop	cx
pop	bx
sub	[word ptr bp+Len], 8000h
sbb	[word ptr bp+Len+2], 0
jmp	short __while_gt_BLK
; ---------------------------------------------------------------------------
__remainder:
mov	cx, [word ptr bp+Len]
jcxz	short __exit
mov	[cs:DPT.sndlen], cx
push	cs
pop	ds
assume ds:_AIL_
mov	si, offset DPT
mov	ax, 68Ah
int	66h				; reserved for user interrupt
__exit:
pop	di
pop	si
pop	ds
assume ds:dseg
pop	bp
retf
endp _DP_preformat
