					; allocation, starting with FirstRec
					; returns a segment pointer to the data
					; quits	on errors
add	sp, 0Ah


push	ax				; addr
call	SA_MK_FP0
pop	cx


mov	[word ptr spell_data_table+2], dx
mov	[word ptr spell_data_table], ax


pop	bp
retf
endp Load_SPELLDAT
