; Attributes: bp-based frame
; int __far Set_Unit_Action_Special(void)
proc Set_Unit_Action_Special far
troops=	word ptr -14h
troop_count= word ptr -2
push	bp
mov	bp, sp
sub	sp, 14h


mov	[special_action_flag], e_ST_UNDEFINED ;	set to indicate	any extra action possible for the
					; selected stack
					;   -1:	no extra action	possible
					;    0:	road building possible
					;    1:	settling possible
					;    2:	purifying possible
					;    9:	melding	possible
lea	ax, [bp+troops]
push	ax				; troops
lea	ax, [bp+troop_count]
push	ax				; troop_count
nop
push	cs
call	near ptr Active_Unit_Stack
pop	cx
pop	cx


lea	ax, [bp+troops]
push	ax				; troops
push	[bp+troop_count]		; troop_count
nop
push	cs
call	near ptr Unit_Action_Special_Build
pop	cx
pop	cx


lea	ax, [bp+troops]
