push	[bp+troop_count]		; Unit_Count
call	j_Unit_Action_Special_Settle
pop	cx
pop	cx


lea	ax, [bp+troops]
push	ax				; troops
push	[bp+troop_count]		; troop_count
nop
push	cs
call	near ptr Unit_Action_Special_Purify
pop	cx
pop	cx


lea	ax, [bp+troops]
push	ax				; troops
push	[bp+troop_count]		; troop_count
nop
push	cs
call	near ptr Unit_Action_Special_Meld
pop	cx
pop	cx


mov	sp, bp
pop	bp
retf
endp Set_Unit_Action_Special
