; on every second call,	advances the unit enchantment
; animation stage by one, wrapping from	7 to 0
; Attributes: bp-based frame
; int __far Cycle_Unit_Enchantment_Animation(void)
proc Cycle_Unit_Enchantment_Animation far
push	bp
mov	bp, sp


mov	ax, [unit_enchantment_animation_flag]
inc	ax
mov	[unit_enchantment_animation_flag], ax


cmp	[unit_enchantment_animation_flag], 1
jle	short loc_560AE
mov	[unit_enchantment_animation_flag], 0
loc_560AE:
cmp	[unit_enchantment_animation_flag], 1
jge	short @@Done
mov	ax, [unit_enchantment_animation_count] ; 8 stages (0 - 7)
inc	ax
mov	[unit_enchantment_animation_count], ax ; 8 stages (0 - 7)


cmp	[unit_enchantment_animation_count], 7 ;	8 stages (0 - 7)
jle	short @@Done
mov	[unit_enchantment_animation_count], 0 ;	8 stages (0 - 7)
@@Done:
pop	bp
retf
endp Cycle_Unit_Enchantment_Animation
