mov	_SI_x1,	[bp+x1]
mov	_DI_y1,	[bp+y1]


mov	ax, cx
mov	bx, 3
cwd
idiv	bx				; ? _DX	= unit_stack_unit_idx /	3 ?
mov	bx, 23				; ? unit window	picture	width +	1 ?
mov	ax, dx
imul	bx
mov	dx, [_unit_window_start_x]	; set to 0F7h
add	dx, ax
mov	[_SI_x1], dx


mov	ax, cx
mov	bx, 3
cwd
idiv	bx
mov	dx, 29				; ? unit window	picture	height + 1 ?
imul	dx
mov	dx, [_unit_window_start_y]	; set to 4Fh
add	dx, ax
mov	[_DI_y1], dx


mov	ax, [_SI_x1]
add	ax, 22				; ? unit window	picture	width ?
mov	bx, [bp+x2]
mov	[bx], ax


mov	ax, [_DI_y1]
add	ax, 28				; ? unit window	picture	height ?
mov	bx, [bp+y2]
mov	[bx], ax


pop	_DI_y1
pop	_SI_x1
pop	bp
retf
endp Unit_Window_Picture_Coords
