; removes the overland unit enchantment(s) specified by
; the passed UE	flags from the unit
; Attributes: bp-based frame
; int __cdecl __far Unit_Remove_Enchantment(int	unit_idx, int enchantment, int Flags_HO)
proc Unit_Remove_Enchantment far
unit_idx= word ptr  6
enchantment= dword ptr	8
_DI_unit_idx = di
push	bp
mov	bp, sp
push	si
push	_DI_unit_idx


mov	_DI_unit_idx, [bp+unit_idx]


mov	ax, _DI_unit_idx
mov	cl, 5
shl	ax, cl
les	bx, [_UNITS]
add	bx, ax
mov	ax, [word ptr es:bx+(s_UNIT.enchantments+2)]
mov	dx, [word ptr es:bx+s_UNIT.enchantments]
xor	dx, [word ptr bp+enchantment]
xor	ax, [word ptr bp+enchantment+2]
mov	bx, _DI_unit_idx
mov	cl, 5
shl	bx, cl
les	si, [_UNITS]
add	si, bx
mov	[word ptr es:si+(s_UNIT.enchantments+2)], ax
mov	[word ptr es:si+s_UNIT.enchantments], dx


pop	_DI_unit_idx
pop	si
pop	bp
retf
endp Unit_Remove_Enchantment
