jz	short @@Done
mov	ax, 255
push	ax				; color
push	[GfxBuf_2400B]			; pict_seg
call	Outline_Bitmap_Pixels_No_Glass
pop	cx
pop	cx


mov	ax, _SI_enchantment_magic_realm
loc_85F5B:
mov	cl, 6
shl	ax, cl
mov	dx, [unit_enchantment_animation_count] ; 8 stages (0 - 7)
mov	cl, 3
shl	dx, cl
add	ax, dx
add	ax, offset enchantment_outline_colors ;	&enchantment_outline_colors[][]
push	ax				; color_list
mov	ax, 255
push	ax				; aura_color
push	[GfxBuf_2400B]			; pict_seg
call	Bitmap_Aura_Pixels
add	sp, 6
@@Done:
pop	_SI_enchantment_magic_realm
pop	bp
retf
endp Combat_Unit_Enchantment_Outline_Draw
