; calculates and returns the wizard's nominal spell
; casting skill	from their stored invested skill
; points, adding 10 for	Archmage if applicable
; Attributes: bp-based frame
; int __cdecl __far Player_Base_Casting_Skill(int player_idx)
proc Player_Base_Casting_Skill far
num= dword ptr -4
player_idx= word ptr  6
_DI_player_idx = di
casting_skill =	cx
twos = si
push	bp
mov	bp, sp
sub	sp, 4
push	twos
