mov	_DI_player_idx,	[bp+player_idx]


xor	twos, twos			; twos = 0;


xor	casting_skill, casting_skill


mov	[word ptr bp+num+2], 0
mov	[word ptr bp+num], 0


jmp	short @@iteration_loop
; ---------------------------------------------------------------------------
@@INC_ADD:
inc	casting_skill


add	twos, 2


mov	ax, twos
cwd					; DX:AX	= AX


add	[word ptr bp+num], ax
adc	[word ptr bp+num+2], dx		; SP_HI	= SP_HI	+ DX + CF
@@iteration_loop:
mov	ax, _DI_player_idx
mov	dx, size s_WIZARD
imul	dx
mov	bx, ax
mov	ax, [word ptr (_players.spell_casting_skill+2)+bx]
mov	dx, [word ptr _players.spell_casting_skill+bx]


cmp	ax, [word ptr bp+num+2]
jg	short @@INC_ADD
jnz	short @@Accumulated_NowDoArchmage
cmp	dx, [word ptr bp+num]
ja	short @@INC_ADD
@@Accumulated_NowDoArchmage:
mov	ax, _DI_player_idx
mov	dx, size s_WIZARD
imul	dx
mov	bx, ax
cmp	[_players.archmage+bx],	0
jle	short @@Done
add	casting_skill, 10
@@Done:
mov	ax, casting_skill


jmp	short $+2


pop	_DI_player_idx
pop	twos
mov	sp, bp
pop	bp
retf
endp Player_Base_Casting_Skill
