push	_SI_stages
push	_DI_x1


mov	_SI_stages, [bp+stages]


xor	ax, ax
push	ax				; Offset
push	[bp+picture_seg]		; Segment
call	farpeekw
pop	cx
pop	cx


mov	[bp+width], ax


