; selects the next production item for a neutral city
; Attributes: bp-based frame
; int __cdecl __far Player_Colony_Autobuild_NP(int City_Index)
proc Player_Colony_Autobuild_NP	far
Weights= word ptr -0D4h
product_array= word ptr	-70h
uu_city_landmass= word ptr -0Ch
need_units= word ptr -0Ah
product_choice=	word ptr -8
product_count= word ptr	-6
uu_unit_count= word ptr	-4
uu_depr_count= word ptr	-2
city_idx= word ptr  6
_DI_itr	= di
push	bp
mov	bp, sp
sub	sp, 0D4h
push	si
push	_DI_itr


lea	ax, [bp+product_array]
push	ax				; Prod_List@
